From: Harry King <d.harry.king@gmail.com>
Date: Thu, 29 Feb 2024 18:46:41 -0800
Subject: [PATCH] JS: remove the horizontal scroll bar reset in getInstance for
 ObjectSelector

Fixes a bug introduced way back in 9e89fc6c1fc522327b0bea270a024f51ff5b120c
(JS: Reset ObjectSelector horz scroll bar to 0 on window open)
that caused the horizontal scroll bar to jitter while a model is running.

Signed-off-by: Harry King <d.harry.king@gmail.com>

diff --git a/src/main/java/com/jaamsim/ui/ObjectSelector.java b/src/main/java/com/jaamsim/ui/ObjectSelector.java
index 7831cce0e..e043b31b8 100644
--- a/src/main/java/com/jaamsim/ui/ObjectSelector.java
+++ b/src/main/java/com/jaamsim/ui/ObjectSelector.java
@@ -127,6 +127,15 @@ public class ObjectSelector extends FrameBox {
 		ToolTipManager.sharedInstance().setDismissDelay(600000);
 	}

+	@Override
+	public void setVisible(boolean bool) {
+		if (bool && !isVisible()) {
+			myInstance.treeView.getHorizontalScrollBar().getModel().setValue(0);
+			myInstance.treeView.getVerticalScrollBar().getModel().setValue(0);
+		}
+		super.setVisible(bool);
+	}
+
 	@Override
 	public void setEntity(Entity ent) {

@@ -201,9 +210,6 @@ public class ObjectSelector extends FrameBox {
 	public static synchronized ObjectSelector getInstance() {
 		if (myInstance == null)
 			myInstance = new ObjectSelector();
-
-		myInstance.treeView.getHorizontalScrollBar().getModel().setValue(0);
-
 		return myInstance;
 	}

